/* Earth textures embedded as data URIs so WebGL can use them even when
 * index.html is opened directly from disk (file://), where browsers block
 * loading local image files into WebGL. Source images: earth-day.jpg, earth-lights.jpg. */
window.AEROLIGHT_TEXTURES = {
  day: "data:image/jpeg;base64,",
  lights: "data:image/jpeg;base64,"
};
